pub fn compare(a: &Version, b: &Version) -> std::cmp::Ordering {
    // Compare component by component, longest wins on a tie.
    let mut a_iter = a.parts.iter().peekable();
    let mut b_iter = b.parts.iter().peekable();

    loop {
        let a_val = a_iter.next().unwrap_or(&0);
        let b_val = b_iter.next().unwrap_or(&0);

        let ord = a_val.cmp(b_val);
        if ord != std::cmp::Ordering::Equal {
            return ord;
        }

        // If both iterators are exhausted, we're done.
        if a_iter.peek().is_none() && b_iter.peek().is_none() {
            break;
        }
    }

    // If we get here, all compared components were equal.
    // The version with more components is greater.
    a.parts.len().cmp(&b.parts.len())
